codes.Python:
def binary_search(arr, target):
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid              # Found!
        elif arr[mid] < target:
            left = mid + 1          # Search right half
        else:
            right = mid - 1         # Search left half
    return -1

sorted_nums = [2, 5, 8, 12, 16, 23, 38, 56]
print(binary_search(sorted_nums, 23))  # Output: 5

