# Check if two elements in a sorted array sum to target
def two_sum_sorted(arr, target):
    left, right = 0, len(arr) - 1
    while left < right:
        current = arr[left] + arr[right]
        if current == target:
            return (left, right)
        elif current < target:
            left += 1   # Need bigger sum — move left pointer right
        else:
            right -= 1  # Need smaller sum — move right pointer left
    return None

print(two_sum_sorted([1, 3, 5, 7, 9], 12))  # Output: (2, 4) → arr[2]+arr[4]=5+9=14? No → (1,4)→3+9=12 ✓

