# Loop , sum of numbers 1 to n
def sum_loop(n):
    total = 0
    for i in range(1, n + 1):
        total += i
    return total

# Recursion , same result
def sum_recursive(n):
    if n == 0:
        return 0
    return n + sum_recursive(n - 1)

print(sum_loop(100))       # 5050
print(sum_recursive(100))  # 5050

