#include<stdio.h>

int main() {
    char name[] = "Harry Potter";

    // Pointer arithmetic to access characters
    printf("%c\n", *name);        // H  (first character)
    printf("%c\n", *(name + 1));  // a  (second character)
    printf("%c\n", *(name + 6));  // P  (seventh character)

    // Using a pointer variable
    char *ptr = name;
    printf("%c\n", *ptr);         // H
    printf("%c\n", *(ptr + 1));   // a

    // Walking through the string with a pointer
    while (*ptr != '\0') {
        printf("%c", *ptr);
        ptr++;
    }
    // Output: Harry Potter

    return 0;
}

