def find_last(arr, target):
    low, high = 0, len(arr) - 1
    result = -1

    while low <= high:
        mid = low + (high - low) // 2

        if arr[mid] == target:
            result = mid         # Record this position
            low = mid + 1        # Keep searching RIGHT for a later occurrence
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    return result

arr = [2, 4, 4, 4, 6, 8, 10]
print(find_last(arr, 4))   # 3 (last occurrence of 4)

def lower_bound(arr, target):
    low, high = 0, len(arr)   # Note: high = len(arr), not len(arr) - 1

    while low < high:
        mid = low + (high - low) // 2
        if arr[mid] < target:
            low = mid + 1
        else:
            high = mid

    return low   # The insertion point

arr = [2, 4, 6, 8, 10]
print(lower_bound(arr, 5))   # 2 (insert 5 at index 2 to maintain order)
print(lower_bound(arr, 4))   # 1 (index of first 4, or where 4 would go)
print(lower_bound(arr, 11))  # 5 (insert at end)

def find_peak(arr):
    low, high = 0, len(arr) - 1

    while low < high:
        mid = low + (high - low) // 2

        if arr[mid] < arr[mid + 1]:
            low = mid + 1     # Peak is in the right half
        else:
            high = mid        # Peak is in the left half (including mid)

    return low   # Index of the peak

arr = [1, 3, 7, 12, 8, 5, 2]
print(find_peak(arr))    # 3 (arr[3] = 12 is the peak)

def search_rotated(arr, target):
    low, high = 0, len(arr) - 1

    while low <= high:
        mid = low + (high - low) // 2

        if arr[mid] == target:
            return mid

        # Left half is sorted
        if arr[low] <= arr[mid]:
            if arr[low] <= target < arr[mid]:
                high = mid - 1    # Target is in the sorted left half
            else:
                low = mid + 1     # Target is in the right half
        # Right half is sorted
        else:
            if arr[mid] < target <= arr[high]:
                low = mid + 1     # Target is in the sorted right half
            else:
                high = mid - 1    # Target is in the left half

    return -1

arr = [4, 5, 6, 7, 0, 1, 2]
print(search_rotated(arr, 0))   # 4
print(search_rotated(arr, 6))   # 2
print(search_rotated(arr, 3))   # -1

def linear_search(arr, target):
    for i in range(len(arr)):
        if arr[i] == target:
            return i
    return -1

