 * Calculates the compound interest earned over a period.
 *
 * <p>Uses the formula: A = P(1 + r/n)^(nt)</p>
 *
 * @paramprincipalthe initial amount of money (must be positive)
 * @paramratethe annual interest rate as a decimal (e.g., 0.05 for 5%)
 * @paramtimesCompoundedthe number of times interest is compounded per year
 * @paramyearsthe number of years the money is invested
 * @return           the total amount after compound interest is applied
 * @throwsIllegalArgumentExceptionif principal or rate is negative
 *
 * @author Finance Team
 * @version 1.2
 * @since 2024-01-01
 */
public double calculateCompoundInterest(double principal, double rate,
                                         int timesCompounded, double years) {
    if (principal < 0 || rate < 0) {
        throw new IllegalArgumentException("Principal and rate must be non-negative");
    }
    return principal * Math.pow(1 + rate / timesCompounded, timesCompounded * years);
}

