class Node {
    int value;
    Node next;
    Node(int value) {
        this.value = value;
        this.next = null;
    }
}

class LinkedStack {
    Node head = null;
    int size = 0;

    void push(int value) {
        Node newNode = new Node(value);
        newNode.next = head;    // Point new node to current top
        head = newNode;         // New node becomes the new top
        size++;
    }

    int pop() {
        if (head == null) throw new RuntimeException("Stack Underflow");
        int value = head.value;
        head = head.next;       // Move top to next node
        size--;
        return value;
    }

    int peek() {
        if (head == null) throw new RuntimeException("Stack is empty");
        return head.value;
    }

    boolean isEmpty() { return head == null; }
    int size() { return size; }
}

