class Node:
    def __init__(self, value):
        self.value = value
        self.next = None   # Points to the node below in the stack

class Stack:
    def __init__(self):
        self.head = None   # Top of the stack
        self.size = 0

    def push(self, value):
        new_node = Node(value)
        new_node.next = self.head   # New node points to current top
        self.head = new_node        # New node becomes the new top
        self.size += 1

    def pop(self):
        if self.is_empty():
            return "Stack Underflow"
        popped = self.head          # Remember the top node
        self.head = self.head.next  # Move top down to next node
        self.size -= 1
        return popped.value

    def peek(self):
        if self.is_empty():
            return "Stack is empty"
        return self.head.value

    def is_empty(self):
        return self.size == 0

    def stack_size(self):
        return self.size

