class QueueUsingTwoStacks:
    def __init__(self):
        self.input_stack = []    # New elements go here
        self.output_stack = []   # Elements come out from here

    def enqueue(self, value):
        self.input_stack.append(value)   # Always push to input stack

    def dequeue(self):
        if not self.output_stack:
            # Transfer all elements from input to output (reversing order)
            while self.input_stack:
                self.output_stack.append(self.input_stack.pop())
        if not self.output_stack:
            return "Queue is empty"
        return self.output_stack.pop()   # FIFO order achieved

q = QueueUsingTwoStacks()
q.enqueue(1); q.enqueue(2); q.enqueue(3)
print(q.dequeue())   # 1 (first in, first out)
print(q.dequeue())   # 2
q.enqueue(4)
print(q.dequeue())   # 3

class MinStack:
    def __init__(self):
        self.stack = []
        self.min_stack = []   # Tracks the minimum at each level

    def push(self, value):
        self.stack.append(value)
        # Push the new minimum: either the new value or the current minimum
        if not self.min_stack or value <= self.min_stack[-1]:
            self.min_stack.append(value)
        else:
            self.min_stack.append(self.min_stack[-1])

    def pop(self):
        self.min_stack.pop()   # Keep both stacks in sync
        return self.stack.pop()

    def get_min(self):
        return self.min_stack[-1]   # O(1): always at the top

