def find_duplicates(arr):
    """Find all duplicates in arr where values are 1 to n."""
    duplicates = []
    for num in arr:
        idx = abs(num) - 1
        if arr[idx] < 0:
            duplicates.append(abs(num))   # Already visited: duplicate
        else:
            arr[idx] = -arr[idx]          # Mark as visited
    return duplicates

print(find_duplicates([4, 3, 2, 7, 8, 2, 3, 1]))   # [2, 3]

