void deleteAtEnd(struct Node **head) {
    if (*head == NULL) { printf("Empty list\n"); return; }
    if ((*head)->next == NULL) { free(*head); *head = NULL; return; }

    struct Node *current = *head;
    while (current->next->next != NULL)   // Stop at second-to-last
        current = current->next;
    free(current->next);   // Free the last node
    current->next = NULL;  // Second-to-last now points to NULL
}

void deleteByValue(struct Node **head, int key) {
    struct Node *temp = *head, *prev = NULL;

    if (temp != NULL && temp->data == key) {
        *head = temp->next;
        free(temp);
        return;
    }

    while (temp != NULL && temp->data != key) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) { printf("Value not found\n"); return; }

    prev->next = temp->next;   // Re-link predecessor to successor
    free(temp);                // Free the deleted node
}

