#include<stdio.h>
#include<stdlib.h>

struct Node {
    int data;
    struct Node *next;
    struct Node *prev;
};

struct Node* createNode(int data) {
    struct Node *node = (struct Node*) malloc(sizeof(struct Node));
    node->data = data;
    node->next = NULL;
    node->prev = NULL;
    return node;
}

int main() {
    struct Node *head = createNode(10);
    head->next = createNode(20);
    head->next->prev = head;

    head->next->next = createNode(30);
    head->next->next->prev = head->next;

    head->next->next->next = createNode(40);
    head->next->next->next->prev = head->next->next;

    // Forward traversal
    struct Node *temp = head;
    while (temp != NULL) {
        printf("%d", temp->data);
        if (temp->next != NULL) printf(" <-> ");
        temp = temp->next;
    }
    printf("\n");   // Output: 10 <-> 20 <-> 30 <-> 40
    return 0;
}

void insertAtBeginning(struct Node **head, struct Node **tail, int data) {
    struct Node *new_node = createNode(data);

    if (*head == NULL) {
        *head = new_node;
        *tail = new_node;
        return;
    }

    new_node->next = *head;     // New node points forward to old head
    (*head)->prev = new_node;   // Old head points backward to new node
    *head = new_node;           // Head updated to new node
}

