void deleteAtEnd(struct Node **head, struct Node **tail) {
    if (*head == NULL) { printf("List is empty\n"); return; }

    struct Node *temp = *tail;
    *tail = (*tail)->prev;           // Move tail back using prev pointer

    if (*tail != NULL) {
        (*tail)->next = NULL;        // New tail has no successor
    } else {
        *head = NULL;                // List became empty
    }

    free(temp);
}

void deleteNode(struct Node **head, struct Node **tail, struct Node *del_node) {
    if (del_node == NULL) return;

    if (*head == del_node) {
        *head = del_node->next;
        if (*head != NULL) (*head)->prev = NULL;
        else *tail = NULL;
        free(del_node);
        return;
    }

    if (del_node->prev != NULL) del_node->prev->next = del_node->next;
    if (del_node->next != NULL) del_node->next->prev = del_node->prev;
    else *tail = del_node->prev;

