class Deque:
    def __init__(self):
        self.dll = DoublyLinkedList()

    def push_front(self, value):
        self.dll.insert_at_beginning(value)

    def push_back(self, value):
        self.dll.insert_at_end(value)

    def pop_front(self):
        if self.dll.is_empty(): return None
        return self.dll.delete_at_beginning()

    def pop_back(self):
        if self.dll.is_empty(): return None
        return self.dll.delete_at_end()

    def peek_front(self):
        return self.dll.head.data if self.dll.head else None

    def peek_back(self):
        return self.dll.tail.data if self.dll.tail else None

    def is_empty(self):
        return self.dll.is_empty()

