def bubble_sort(self):
    """Sort the doubly linked list using bubble sort on data values."""
    if self.is_empty() or self.head == self.tail:
        return

    sorted_flag = True
    while sorted_flag:
        sorted_flag = False
        current = self.head
        while current.next:
            if current.data > current.next.data:
                # Swap data values (not nodes, to preserve pointer structure)
                current.data, current.next.data = current.next.data, current.data
                sorted_flag = True
            current = current.next

