class CircularBuffer:
    def __init__(self, capacity):
        self.buffer = [None] * capacity
        self.capacity = capacity
        self.head = 0    # Read position
        self.tail = 0    # Write position
        self.size = 0

    def write(self, data):
        self.buffer[self.tail] = data
        self.tail = (self.tail + 1) % self.capacity   # Circular wrap
        if self.size < self.capacity:
            self.size += 1
        else:
            self.head = (self.head + 1) % self.capacity   # Overwrite oldest

    def read(self):
        if self.size == 0:
            return None
        data = self.buffer[self.head]
        self.head = (self.head + 1) % self.capacity   # Circular wrap
        self.size -= 1
        return data

    def is_full(self):
        return self.size == self.capacity

