import java.util.Arrays;

public class Queue {
    private int[] queue;
    private int front, rear, size, capacity;

    public Queue(int capacity) {
        this.capacity = capacity;
        this.queue = new int[capacity];
        this.front = 0;
        this.rear = -1;
        this.size = 0;
    }

    public void enqueue(int element) {
        if (isFull()) { throw new RuntimeException("Queue Overflow"); }
        queue[++rear] = element;
        size++;
    }

    public int dequeue() {
        if (isEmpty()) { throw new RuntimeException("Queue Underflow"); }
        int element = queue[front++];
        size--;
        return element;
    }

    public int peek() {
        if (isEmpty()) { throw new RuntimeException("Queue is empty"); }
        return queue[front];
    }

    public boolean isEmpty() { return size == 0; }
    public boolean isFull()  { return size == capacity; }
    public int size()        { return size; }

    public static void main(String[] args) {
        Queue q = new Queue(6);
        int[] values = {3, 5, 9, 1, 12, 15};
        for (int v : values) q.enqueue(v);

        System.out.println("Queue size: " + q.size());   // 6
        System.out.println("Is full: " + q.isFull());    // true
        System.out.println("Dequeued: " + q.dequeue());  // 3
        System.out.println("Front: " + q.peek());        // 5
        System.out.println("Is full: " + q.isFull());    // false
    }
}

class LinkedQueue {
    static class Node {
        int data;
        Node next;
        Node(int data) { this.data = data; }
    }

    Node front, rear;
    int size = 0;

    void enqueue(int data) {
        Node newNode = new Node(data);
        if (rear == null) { front = rear = newNode; }
        else { rear.next = newNode; rear = newNode; }
        size++;
    }

    int dequeue() {
        if (front == null) throw new RuntimeException("Queue is empty");
        int data = front.data;
        front = front.next;
        if (front == null) rear = null;
        size--;
        return data;
    }
}

