class QueueUsingStacks:
    def __init__(self):
        self.inbox = []     # For enqueue: push here
        self.outbox = []    # For dequeue: pop from here

    def enqueue(self, value):
        self.inbox.append(value)   # Always push to inbox

    def dequeue(self):
