def extract_max(self):
    if not self.heap:
        print("Priority queue is empty")
        return None

    max_val = self.heap[0]                   # Step 1: Save root
    self.heap[0] = self.heap[-1]             # Step 2: Move last to root
    self.heap.pop()                          # Step 3: Remove last
    self._bubble_down(0)                     # Step 4: Restore heap
    return max_val

def _bubble_down(self, i):
    n = len(self.heap)
    while True:
        largest = i
        left  = self._left(i)
        right = self._right(i)

        if left < n and self.heap[left] > self.heap[largest]:
            largest = left
        if right < n and self.heap[right] > self.heap[largest]:
            largest = right

        if largest != i:
            self.heap[i], self.heap[largest] = self.heap[largest], self.heap[i]
            i = largest
        else:
            break

