import heapq

def k_largest(arr, k):
    """Find k largest elements using a min-heap of size k."""
    min_heap = []
    for num in arr:
        heapq.heappush(min_heap, num)
        if len(min_heap) > k:
            heapq.heappop(min_heap)   # Remove smallest, keeping only top-k
    return sorted(min_heap, reverse=True)

def k_smallest(arr, k):
    """Find k smallest elements using a max-heap of size k."""
    max_heap = []
    for num in arr:
        heapq.heappush(max_heap, -num)   # Negate for max-heap behaviour
        if len(max_heap) > k:
            heapq.heappop(max_heap)       # Remove largest (least negative)
    return sorted([-x for x in max_heap])

