class Deque {
    private int[] arr;
    private int front, rear, size, capacity;

    Deque(int capacity) {
        this.capacity = capacity;
        arr = new int[capacity];
        front = rear = -1;
        size = 0;
    }

    boolean isEmpty() { return front == -1; }
    boolean isFull()  { return size == capacity; }
    int getSize()     { return size; }

    void pushFront(int element) {
        if (isFull()) { System.out.println("Overflow"); return; }
        if (isEmpty()) { front = rear = 0; }
        else { front = (front - 1 + capacity) % capacity; }
        arr[front] = element;
        size++;
    }

    void pushBack(int element) {
        if (isFull()) { System.out.println("Overflow"); return; }
        if (isEmpty()) { front = rear = 0; }
        else { rear = (rear + 1) % capacity; }
        arr[rear] = element;
        size++;
    }

    int popFront() {
        if (isEmpty()) throw new RuntimeException("Underflow");
        int value = arr[front];
        if (front == rear) { front = rear = -1; }
        else { front = (front + 1) % capacity; }
        size--;
        return value;
    }

    int popBack() {
        if (isEmpty()) throw new RuntimeException("Underflow");
        int value = arr[rear];
        if (front == rear) { front = rear = -1; }
        else { rear = (rear - 1 + capacity) % capacity; }
        size--;
        return value;
    }

    int peekFront() { return isEmpty() ? -1 : arr[front]; }
    int peekBack()  { return isEmpty() ? -1 : arr[rear]; }

    public static void main(String[] args) {
        Deque dq = new Deque(6);
