def binary_search(arr, target):
    """Find target in sorted array. Halves the search space each step."""
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = left + (right - left) // 2   # Safe midpoint (avoids overflow)

        if arr[mid] == target:
            return mid          # Found: O(log n) steps total
        elif arr[mid] < target:
            left = mid + 1      # Target in right half: discard left half
        else:
            right = mid - 1     # Target in left half: discard right half

    return -1   # Not found

