import java.util.*;

public class DijkstraPQ {
    static int[] dijkstra(List<int[]>[] graph, int start, int n) {
        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[start] = 0;

        // Min-heap: {distance, vertex}
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        pq.offer(new int[]{0, start});

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int d = curr[0], u = curr[1];

            if (d > dist[u]) continue;   // Skip outdated entries

            for (int[] edge : graph[u]) {
                int v = edge[0], weight = edge[1];
                int newDist = dist[u] + weight;
                if (newDist < dist[v]) {
                    dist[v] = newDist;
                    pq.offer(new int[]{newDist, v});
                }
            }
        }
        return dist;
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) {
        int n = 7;
        List<int[]>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();

        int[][] edges = {{3,0,4},{3,4,2},{0,2,3},{0,4,4},{4,2,4},{4,6,5},{2,5,5},{2,1,2},{1,5,2},{6,5,5}};
        for (int[] e : edges) {
            graph[e[0]].add(new int[]{e[1], e[2]});
            graph[e[1]].add(new int[]{e[0], e[2]});  // undirected
        }

        int[] dist = dijkstra(graph, 3, n);
        String[] v = {"A","B","C","D","E","F","G"};
        for (int i = 0; i < n; i++) System.out.println("D → " + v[i] + ": " + dist[i]);
