import java.util.*;

// Complete Java implementation with path reconstruction
public class DijkstraComplete {

    static class Edge {
        int to, weight;
        Edge(int to, int weight) { this.to = to; this.weight = weight; }
    }

    static int[] dist;
    static int[] pred;

    static void dijkstra(List<Edge>[] graph, int src) {
        int n = graph.length;
        dist = new int[n];
        pred = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        Arrays.fill(pred, -1);
        dist[src] = 0;

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        pq.offer(new int[]{0, src});

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int d = curr[0], u = curr[1];
            if (d > dist[u]) continue;
            for (Edge e : graph[u]) {
                if (dist[u] + e.weight < dist[e.to]) {
                    dist[e.to] = dist[u] + e.weight;
                    pred[e.to] = u;
                    pq.offer(new int[]{dist[e.to], e.to});
                }
            }
        }
    }

    static String getPath(int end, String[] vertices) {
        List<String> path = new ArrayList<>();
        int cur = end;
        while (cur != -1) {
            path.add(0, vertices[cur]);
            cur = pred[cur];
        }
        return String.join(" → ", path);
    }

    public static void main(String[] args) {
        int n = 7;
        String[] vertices = {"A", "B", "C", "D", "E", "F", "G"};
        List<Edge>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();

        int[][] edges = {{3,0,4},{3,4,2},{0,2,3},{0,4,4},{4,2,4},{4,6,5},{2,5,5},{2,1,2},{1,5,2},{6,5,5}};
        for (int[] e : edges) {
            graph[e[0]].add(new Edge(e[1], e[2]));
            graph[e[1]].add(new Edge(e[0], e[2]));
        }

        dijkstra(graph, 3); // Source: D = index 3
        for (int i = 0; i < n; i++) {
            System.out.println(getPath(i, vertices) + "  (cost: " + dist[i] + ")");
        }
    }
}

