class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, data):
        new_node = Node(data)
        if not self.head:
            self.head = new_node
            return
        current = self.head
        while current.next:
            current = current.next
        current.next = new_node

    def linear_search(self, target):
        """Linear search on linked list. Returns position (0-indexed) or -1."""
        current = self.head
        position = 0
        while current:
            if current.data == target:
                print(f"Found{target} at position{position}")
                return position
            current = current.next
            position += 1
        print(f"{target} not found in linked list")
        return -1

