void bubbleSort(int[] arr) {
    int n = arr.length;
    for (int i = 0; i < n; i++) {         // O(n): outer loop
        for (int j = 0; j < n-i-1; j++) { // O(n): inner loop
            if (arr[j] > arr[j+1]) {
                int temp = arr[j];
                arr[j] = arr[j+1];
                arr[j+1] = temp;
            }
        }
    }
    // Total: O(n) × O(n) = O(n²)
