void reverseInPlace(int[] arr) {
    int left = 0, right = arr.length - 1;
    while (left < right) {
        int temp = arr[left];   // O(1): just one temp variable
        arr[left] = arr[right];
        arr[right] = temp;
        left++;
        right--;
    }
    // Auxiliary: O(1). Space complexity: O(n) input + O(1) aux = O(n)
}

