def remove_duplicates_inplace(arr):
    """Remove duplicates from sorted array in-place. O(1) auxiliary."""
    if not arr: return 0
    write = 1
    for read in range(1, len(arr)):
        if arr[read] != arr[write - 1]:
            arr[write] = arr[read]
            write += 1
    return write   # New length (elements beyond index write are garbage)

