def edit_distance_full(s1, s2):
    m, n = len(s1), len(s2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]   # O(m×n)
    for i in range(m + 1): dp[i][0] = i
    for j in range(n + 1): dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i-1] == s2[j-1]: dp[i][j] = dp[i-1][j-1]
            else: dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])
    return dp[m][n]

# Rolling array: O(n) space (only two rows at a time)
def edit_distance_optimised(s1, s2):
    m, n = len(s1), len(s2)
    prev = list(range(n + 1))   # Previous row: O(n)
    curr = [0] * (n + 1)        # Current row: O(n)

    for i in range(1, m + 1):
        curr[0] = i
        for j in range(1, n + 1):
            if s1[i-1] == s2[j-1]: curr[j] = prev[j-1]
            else: curr[j] = 1 + min(prev[j], curr[j-1], prev[j-1])
        prev, curr = curr, [0] * (n + 1)

    return prev[n]

