public class CircularQueue {
    private int[] queue;
    private int front, rear, size, capacity;

    public CircularQueue(int capacity) {
        this.capacity = capacity;
        queue = new int[capacity];
        front = rear = -1;
        size = 0;
    }

    public boolean isEmpty() { return front == -1; }
    public boolean isFull()  { return size == capacity; }
    public int getSize()     { return size; }

    public void enqueue(int element) {
        if (isFull()) { System.out.println("Queue Overflow"); return; }
        if (isEmpty()) { front = rear = 0; }
        else { rear = (rear + 1) % capacity; }
        queue[rear] = element;
        size++;
    }

    public int dequeue() {
        if (isEmpty()) throw new RuntimeException("Queue Underflow");
        int value = queue[front];
        if (front == rear) { front = rear = -1; }
        else { front = (front + 1) % capacity; }
        size--;
        return value;
    }

    public int peek()    { return isEmpty() ? -1 : queue[front]; }
    public int getRear() { return isEmpty() ? -1 : queue[rear]; }

    public void display() {
        if (isEmpty()) { System.out.println("[ Empty Queue ]"); return; }
        System.out.print("Queue: [ ");
        int i = front;
        for (int c = 0; c < size; c++) {
            System.out.print(queue[i] + " ");
            i = (i + 1) % capacity;
        }
        System.out.printf("] FRONT=%d REAR=%d%n", front, rear);
    }

    public static void main(String[] args) {
        CircularQueue cq = new CircularQueue(5);
        for (int v : new int[]{10, 20, 30, 40, 50}) cq.enqueue(v);
        cq.display();                                  // [ 10 20 30 40 50 ]
        System.out.println("Dequeue: " + cq.dequeue()); // 10
        System.out.println("Dequeue: " + cq.dequeue()); // 20
        cq.enqueue(60);    // Wraps to index 0
        cq.enqueue(70);    // Goes to index 1
        cq.display();      // [ 30 40 50 60 70 ]
        System.out.println("Peek: " + cq.peek());      // 30
    }
}

