struct Node {
    int data;
    struct Node* link;
};

struct Node* front = NULL;
struct Node* rear = NULL;

bool is_empty_ll() { return front == NULL; }

void enqueue_ll(int value) {
    struct Node* newNode = (struct Node*) malloc(sizeof(struct Node));
    newNode->data = value;
    newNode->link = NULL;
    if (is_empty_ll()) {
        front = newNode;
    } else {
        rear->link = newNode;
    }
    rear = newNode;
    rear->link = front;   // Maintain circular link: rear always points to front
}

int dequeue_ll() {
    if (is_empty_ll()) { printf("Queue is empty\n"); return -1; }
    int value;
    struct Node* temp = front;
    value = temp->data;
    if (front == rear) {
        front = rear = NULL;
    } else {
        front = front->link;
        rear->link = front;   // Keep circular
    }
    free(temp);
    return value;
}

void display_ll() {
    if (is_empty_ll()) { printf("Queue is empty\n"); return; }
    struct Node* temp = front;
    printf("Queue: ");
    do {
        printf("%d -> ", temp->data);
        temp = temp->link;
    } while (temp != front);
    printf("(front)\n");
}

