void countByDigit(int[] arr, int exp) {
    int n = arr.length;
    int[] out = new int[n], cnt = new int[10];
    for (int x : arr) cnt[(x/exp)%10]++;
    for (int i = 1; i < 10; i++) cnt[i] += cnt[i-1];
    for (int i = n-1; i >= 0; i--) out[--cnt[(arr[i]/exp)%10]] = arr[i];
    System.arraycopy(out, 0, arr, 0, n);
}

