class FlashMemorySimulator:
    """Simulates flash memory with write-cycle tracking."""
    def __init__(self, data):
        self.cells = list(data)
        self.write_count = [0] * len(data)   # Track writes per cell

    def write(self, index, value):
        self.cells[index] = value
        self.write_count[index] += 1

    def sort_selection(self):
        """Sort using selection sort: minimise writes to flash cells."""
        n = len(self.cells)
        for i in range(n - 1):
            min_idx = i
            for j in range(i + 1, n):
                if self.cells[j] < self.cells[min_idx]:
                    min_idx = j
            if min_idx != i:
                temp = self.cells[i]
                self.write(i, self.cells[min_idx])   # Write 1
                self.write(min_idx, temp)              # Write 2
        return self.cells

    def sort_bubble(self):
        """Compare: bubble sort makes many more writes."""
        n = len(self.cells)
        for i in range(n - 1):
            for j in range(n - i - 1):
                if self.cells[j] > self.cells[j + 1]:
                    temp = self.cells[j]
                    self.write(j, self.cells[j + 1])
                    self.write(j + 1, temp)
        return self.cells

