flash1.sort_selection()
print(f"Selection sort total writes:{sum(flash1.write_count)}")   # ~6 writes max

flash2 = FlashMemorySimulator([64, 25, 12, 22, 11, 90])
flash2.sort_bubble()
print(f"Bubble sort total writes:{sum(flash2.write_count)}")   # Many more writes

