        for (int j = 0; j < n - i - 1; j++) {
            if (window[j] > window[j + 1]) {
                float temp    = window[j];
                window[j]     = window[j + 1];
                window[j + 1] = temp;
                swapped       = 1;
            }
        }
        if (!swapped) break;
    }
}

float median_filter(float readings[], int n) {
    float window[WINDOW_SIZE];
    for (int i = 0; i < WINDOW_SIZE; i++) window[i] = readings[i];
    sort_window(window, WINDOW_SIZE);
    return window[WINDOW_SIZE / 2];   /* Middle element = median */
}

