import random

def generate_log_entries(n):
    """Simulate log entries from multiple servers arriving out of order."""
    return [
        {
            "timestamp": random.randint(1700000000, 1700100000),
            "server":    f"server-{random.randint(1, 10)}",
            "level":     random.choice(["INFO", "WARN", "ERROR"]),
            "message":   f"Event{i}"
        }
        for i in range(n)
    ]

def sort_logs_by_timestamp(logs):
    """Quick sort logs by timestamp: O(n log n) in-place."""
    n = len(logs)

    def partition_logs(low, high):
        pivot_ts = logs[high]["timestamp"]
        i = low - 1
        for j in range(low, high):
            if logs[j]["timestamp"] <= pivot_ts:
                i += 1
                logs[i], logs[j] = logs[j], logs[i]
        logs[i + 1], logs[high] = logs[high], logs[i + 1]
        return i + 1

    def qsort(low, high):
        if low < high:
            pi = partition_logs(low, high)
            qsort(low, pi - 1)
            qsort(pi + 1, high)

    qsort(0, n - 1)
    return logs

