def search_bst(root, target):
    """
    Search for a value in a BST.
    Time: O(h) where h is height. O(log n) balanced, O(n) worst.
    """
    if root is None:
        return False    # Not found

    if root.data == target:
        return True     # Found!

    if target < root.data:
        return search_bst(root.left, target)    # Search left
    else:
        return search_bst(root.right, target)   # Search right

