def height(root):
    """
    Find the height of the tree (longest root-to-leaf path in edges).
    Time: O(n): must visit every node.
    """
    if root is None:
        return -1   # Empty tree has height -1 (or 0 depending on convention)

    left_height  = height(root.left)
    right_height = height(root.right)

    return 1 + max(left_height, right_height)

