class BinaryTree:
    def __init__(self):
        self.root = None

    def insert(self, data):
        """Insert using level-order to maintain complete binary tree shape."""
        new_node = TreeNode(data)
        if not self.root:
            self.root = new_node
            return

        queue = deque([self.root])
        while queue:
            node = queue.popleft()
            if not node.left:
                node.left = new_node
                return
            queue.append(node.left)
            if not node.right:
                node.right = new_node
                return
            queue.append(node.right)

    def height(self):
        return height(self.root)

    def count(self):
        return count_nodes(self.root)

    def inorder(self):
        return inorder(self.root)

    def level_order(self):
        return level_order(self.root)

    def display(self):
        """Print tree level by level."""
        levels = self.level_order()
        for i, level in enumerate(levels):
            print(f"Level{i}:{level}")

