def find_file(node, target_name):
    """
    Search for a file/folder in a file system tree.
    Uses DFS preorder traversal.
    Time: O(n) in worst case (file not present).
    """
    if node is None:
        return None

    if node.data == target_name:
        return node   # Found!

    for child in node.children:
        result = find_file(child, target_name)
        if result:
            return result

    return None   # Not in this subtree

def calculate_directory_size(node, file_sizes):
    """
    Calculate total size of a directory and all its contents.
    Uses DFS postorder: compute children first, then add to parent.
    Time: O(n).
    """
    if not node.children:
        return file_sizes.get(node.data, 0)   # Leaf = file with known size

    total = 0
    for child in node.children:
        total += calculate_directory_size(child, file_sizes)
    return total

