class TrieNode:
    def __init__(self):
        self.children  = {}      # Map: character → TrieNode
        self.is_end    = False   # True if this node ends a word
        self.word      = None    # The complete word ending here

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        """Insert a word into the trie. Time: O(L)."""
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end = True
        node.word   = word

    def autocomplete(self, prefix):
        """Find all words with given prefix. Time: O(L + matches)."""
        node = self.root
        for char in prefix:
            if char not in node.children:
                return []   # No words with this prefix
            node = node.children[char]

        results = []
        self._collect_words(node, results)
        return results

    def _collect_words(self, node, results):
        if node.is_end:
            results.append(node.word)
        for child in node.children.values():
            self._collect_words(child, results)

