def height(root):
    """
    Height = number of edges on longest root-to-leaf path.
    Empty tree: height = -1. Single node: height = 0.
    Time: O(n). Must visit every node to find the deepest path.
    """
    if root is None:
        return -1   # Empty subtree contributes -1 to height
    return 1 + max(height(root.left), height(root.right))

print(height(root))   # 2 for a 3-level tree (root + 2 levels below)

def count_nodes(root):
    """Count all nodes. Time: O(n)."""
    if root is None: return 0
    return 1 + count_nodes(root.left) + count_nodes(root.right)

def count_leaves(root):
    """Count leaf nodes (both children are None). Time: O(n)."""
    if root is None: return 0
    if root.left is None and root.right is None:
        return 1   # This node is a leaf
    return count_leaves(root.left) + count_leaves(root.right)

def count_internal(root):
    """Count internal nodes (has at least one child). Time: O(n)."""
    if root is None or (root.left is None and root.right is None):
        return 0
    return 1 + count_internal(root.left) + count_internal(root.right)

