def delete(root, target):
    """
    Delete a node with the target value from a binary tree.
    Replaces with deepest rightmost node to maintain completeness.
    Time: O(n). Space: O(w).
    """
    if root is None: return None

    if root.left is None and root.right is None:
        return None if root.data == target else root

    queue       = deque([root])
    target_node = None
    last_node   = None
    last_parent = None

    while queue:
        last_node = queue.popleft()

        if last_node.data == target:
            target_node = last_node

        if last_node.left:
            last_parent = last_node
            queue.append(last_node.left)

        if last_node.right:
            last_parent = last_node
            queue.append(last_node.right)

    if target_node:
        target_node.data = last_node.data   # Copy deepest value
        if last_parent:
            if last_parent.right == last_node:
                last_parent.right = None
            else:
                last_parent.left = None

    return root

def search(root, target):
    """
    Search for target value in a binary tree.
    Uses BFS (level-order) for systematic search.
    Time: O(n) worst case (target not present or at last node).
    """
    if root is None:
        return False

    queue = deque([root])
    while queue:
        node = queue.popleft()
        if node.data == target:
            return True           # Found!
        if node.left:  queue.append(node.left)
        if node.right: queue.append(node.right)

    return False   # Not found

# DFS search (recursive)
def search_dfs(root, target):
    """Search using DFS. Returns True if target found."""
    if root is None:
        return False
    if root.data == target:
        return True
    return search_dfs(root.left, target) or search_dfs(root.right, target)

print(search(root, 5))    # True
print(search(root, 99))   # False

