import heapq

class MinHeap:
    """Min-heap using Python's heapq module (binary tree internally)."""
    def __init__(self):
        self.heap = []

    def insert(self, val):
        """Insert into heap. O(log n) to maintain heap property."""
        heapq.heappush(self.heap, val)
        print(f"Inserted{val}, heap:{self.heap}")

    def extract_min(self):
        """Remove and return minimum element. O(log n)."""
        if not self.heap:
            return None
        return heapq.heappop(self.heap)

    def peek_min(self):
        """View minimum without removing. O(1)."""
        return self.heap[0] if self.heap else None

