from collections import defaultdict, deque

class Graph:
    def __init__(self, directed=False):
        self.adj      = defaultdict(list)
        self.directed = directed
        self.vertices = set()

    def add_vertex(self, v):
        """Add a vertex. Time: O(1)."""
        self.vertices.add(v)
        if v not in self.adj: self.adj[v] = []

    def add_edge(self, u, v, weight=None):
        """Add an edge. Time: O(1)."""
        self.add_vertex(u); self.add_vertex(v)
        entry = (v, weight) if weight else v
        self.adj[u].append(entry)
        if not self.directed:
            reverse = (u, weight) if weight else u
            self.adj[v].append(reverse)

    def has_edge(self, u, v):
        """Check if edge (u,v) exists. Time: O(degree(u))."""
        return v in self.adj[u]

    def degree(self, v):
        """Get degree of vertex v."""
        return len(self.adj[v])

    def display(self):
        for v in sorted(self.vertices):
            print(f"{v} →{self.adj[v]}")

g = Graph()
for u, v in [(0,1),(0,3),(1,2),(2,3),(3,4)]:
    g.add_edge(u, v)
g.display()
# 0 → [1, 3]   1 → [0, 2]   2 → [1, 3]   3 → [0, 2, 4]   4 → [3]
print(g.has_edge(0, 1))   # True
print(g.has_edge(0, 2))   # False
print(g.degree(3))         # 3

def dfs_recursive(graph, start, visited=None, result=None):
    """
    Recursive DFS. Time: O(V + E). Space: O(V) + O(h) call stack.
    """
    if visited is None: visited = set()
    if result  is None: result  = []
    visited.add(start); result.append(start)
    for neighbour in graph.adj[start]:
        if neighbour not in visited:
            dfs_recursive(graph, neighbour, visited, result)
    return result

def dfs_iterative(graph, start):
    """
    Iterative DFS using explicit stack. Avoids recursion depth limits.
    Time: O(V + E). Space: O(V).
    """
    visited = set(); stack = [start]; result = []
    while stack:
        vertex = stack.pop()
        if vertex not in visited:
            visited.add(vertex); result.append(vertex)
            for n in reversed(graph.adj[vertex]):
                if n not in visited: stack.append(n)
    return result

