def bfs(graph, start):
    """
    BFS traversal. Time: O(V + E). Space: O(V).
    Guarantees shortest path (by hop count) in unweighted graphs.
    """
    visited = {start}; queue = deque([start]); result = []
    while queue:
        v = queue.popleft(); result.append(v)
        for n in graph.adj[v]:
            if n not in visited:
                visited.add(n); queue.append(n)
    return result

def bfs_shortest_path(graph, start, end):
    """Find shortest path (fewest hops) from start to end."""
    visited = {start}
    queue   = deque([(start, [start])])
    while queue:
        v, path = queue.popleft()
        if v == end: return path
        for n in graph.adj[v]:
            if n not in visited:
                visited.add(n)
                queue.append((n, path + [n]))
    return []   # No path exists

print("BFS order:    ", bfs(g, 0))                  # [0, 1, 2, 3, 4]
print("Path 0 → 3:  ", bfs_shortest_path(g, 0, 3)) # [0, 1, 3]

