import java.util.*;

class Graph {
    private int V;
    private List<List<Integer>> adj;
    private boolean directed;

    Graph(int V, boolean directed) {
        this.V = V; this.directed = directed;
        adj = new ArrayList<>();
        for (int i = 0; i < V; i++) adj.add(new ArrayList<>());
    }

    void addEdge(int u, int v) {
        adj.get(u).add(v);
        if (!directed) adj.get(v).add(u);
    }

    List<Integer> dfs(int start) {
        boolean[] vis = new boolean[V];
        List<Integer> res = new ArrayList<>();
        dfsHelper(start, vis, res);
        return res;
    }

    private void dfsHelper(int v, boolean[] vis, List<Integer> res) {
        vis[v] = true; res.add(v);
        for (int n : adj.get(v)) if (!vis[n]) dfsHelper(n, vis, res);
    }

    List<Integer> bfs(int start) {
        boolean[] vis = new boolean[V];
        List<Integer> res = new ArrayList<>();
        Queue<Integer> q = new LinkedList<>();
        vis[start] = true; q.add(start);
        while (!q.isEmpty()) {
            int v = q.poll(); res.add(v);
            for (int n : adj.get(v))
                if (!vis[n]) { vis[n] = true; q.add(n); }
        }
        return res;
    }

    public static void main(String[] args) {
        Graph g = new Graph(5, false);
        int[][] edges = {{0,1},{0,2},{1,3},{1,4},{2,4}};
        for (int[] e : edges) g.addEdge(e[0], e[1]);
        System.out.println("DFS: " + g.dfs(0));   // [0, 1, 3, 4, 2]
        System.out.println("BFS: " + g.bfs(0));   // [0, 1, 2, 3, 4]
    }
}

