def recommend_friends(social_graph, person, max_hops=2):
    """
    Find people within max_hops in a social graph.
    Hop 1 = direct friends. Hop 2 = friends-of-friends (recommendations).
    BFS gives exactly this level-by-level distance information.
    """
    visited  = {person}; by_level = {}
    queue    = deque([(person, 0)])

    while queue:
        current, hop = queue.popleft()
        if hop > max_hops: break
        if hop > 0:
            by_level.setdefault(hop, []).append(current)
        if hop < max_hops:
            for friend in social_graph.adj[current]:
                if friend not in visited:
                    visited.add(friend)
                    queue.append((friend, hop + 1))
    return by_level

