for u, v in [("Alice","Bob"),("Alice","Carol"),("Bob","David"),
             ("Carol","Eve"),("David","Frank")]:
    social.add_edge(u, v)

recs = recommend_friends(social, "Alice", max_hops=2)
for hop, people in recs.items():
    print(f"Hop{hop}:{people}")
# Hop 1: ['Bob', 'Carol']    ← direct friends
# Hop 2: ['David', 'Eve']    ← friends-of-friends (recommendations!)

def topological_sort(graph, V):
    """
    Topological sort using DFS post-order.
    Only valid for DAGs. Time: O(V + E). Space: O(V).
    """
    visited = set(); stack = []

    def dfs(v):
        visited.add(v)
        for n in graph.adj[v]:
            if n not in visited: dfs(n)
        stack.append(v)   # Append AFTER all descendants (post-order)

    for v in range(V):
        if v not in visited: dfs(v)

    return stack[::-1]   # Reverse: ready tasks come first

# Task dependencies: 5→2, 5→0, 4→0, 4→1, 2→3, 3→1
g_topo = Graph(directed=True)
for u, v in [(5,2),(5,0),(4,0),(4,1),(2,3),(3,1)]:
    g_topo.add_edge(u, v)
print("Execution order:", topological_sort(g_topo, 6))
# [5, 4, 2, 3, 1, 0] or similar valid order

def connected_components(graph, V):
    """
    Find all connected components. Time: O(V + E).
    Each DFS from an unvisited vertex discovers one complete component.
    """
    visited = set(); components = []

    def dfs(v, comp):
        visited.add(v); comp.append(v)
        for n in graph.adj[v]:
            if n not in visited: dfs(n, comp)

    for v in range(V):
        if v not in visited:
            comp = []; dfs(v, comp); components.append(comp)

    return components

