class AVLNode {
    int data, height;
    AVLNode left, right;
    AVLNode(int data) { this.data = data; this.height = 1; }
}

static int height(AVLNode n) { return n == null ? 0 : n.height; }
static int balance(AVLNode n) { return n == null ? 0 : height(n.left) - height(n.right); }

static AVLNode insert(AVLNode node, int data) {
    if (node == null) return new AVLNode(data);
    if (data < node.data) node.left  = insert(node.left,  data);
    else if (data > node.data) node.right = insert(node.right, data);
    else return node;

    node.height = 1 + Math.max(height(node.left), height(node.right));
    int bf = balance(node);

    if (bf > 1  && data < node.left.data)  return rightRotate(node);         // LL
    if (bf < -1 && data > node.right.data) return leftRotate(node);          // RR
    if (bf > 1  && data > node.left.data)  { node.left  = leftRotate(node.left);  return rightRotate(node); }  // LR
    if (bf < -1 && data < node.right.data) { node.right = rightRotate(node.right); return leftRotate(node); }  // RL
    return node;
}

