class AVLNode:
    def __init__(self, data):
        self.data   = data
        self.left   = None
        self.right  = None
        self.height = 1   # New node starts with height 1

def insert(node, data):
    """
    AVL insertion: BST insert + balance check + rotation if needed.
    Time: O(log n). Space: O(log n) recursion stack.
    """
    # Step 1: Standard BST insertion
    if not node:
        return AVLNode(data)
    if data < node.data:
        node.left  = insert(node.left,  data)
    elif data > node.data:
        node.right = insert(node.right, data)
    else:
        return node   # Duplicate: no change

    # Step 2: Update height
    node.height = 1 + max(get_height(node.left), get_height(node.right))

    # Step 3: Check balance
    balance = get_balance(node)

    # Step 4: Apply rotation if unbalanced
    if balance > 1 and data < node.left.data:       # LL case
        return right_rotate(node)

    if balance < -1 and data > node.right.data:     # RR case
        return left_rotate(node)

    if balance > 1 and data > node.left.data:       # LR case
        node.left = left_rotate(node.left)
        return right_rotate(node)

    if balance < -1 and data < node.right.data:     # RL case
        node.right = right_rotate(node.right)
        return left_rotate(node)

    return node   # Balanced: return unchanged

# Build AVL tree
