from collections import deque

def bfs(graph, start):
    visited = {start}
    queue   = deque([start])
    result  = []

    while queue:
        node = queue.popleft()
        result.append(node)
        for neighbour in graph[node]:
            if neighbour not in visited:
                visited.add(neighbour)
                queue.append(neighbour)
    return result

