static int[] dijkstra(int[][] graph, int src) {
    int n = graph.length;
    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[src] = 0;
    boolean[] visited = new boolean[n];
    PriorityQueue<int[]> pq = new PriorityQueue<>((a,b)->a[0]-b[0]);
    pq.offer(new int[]{0, src});
    while (!pq.isEmpty()) {
        int[] curr = pq.poll(); int d=curr[0], u=curr[1];
        if (visited[u]) continue; visited[u]=true;
        for (int v=0; v<n; v++) if (graph[u][v]>0 && !visited[v])
            if (dist[u]+graph[u][v]<dist[v]) { dist[v]=dist[u]+graph[u][v]; pq.offer(new int[]{dist[v],v}); }
    }
    return dist;
}

