function dijkstra(graph, start) {
    const dist = {};
    Object.keys(graph).forEach(n => dist[n] = Infinity);
    dist[start] = 0;

    const visited = new Set();
    while (visited.size < Object.keys(graph).length) {
        // Get unvisited node with smallest distance
        const node = Object.keys(dist)
            .filter(n => !visited.has(n))
            .reduce((a, b) => dist[a] < dist[b] ? a : b);
        visited.add(node);
        for (const [nb, w] of graph[node])
            if (dist[node] + w < dist[nb]) dist[nb] = dist[node] + w;
    }
    return dist;
}

