import java.util.*;

class KMP {
    static int[] computeLPS(String pat) {
        int m = pat.length();
        int[] lps = new int[m];
        int length = 0, i = 1;

        while (i < m) {
            if (pat.charAt(i) == pat.charAt(length)) {
                lps[i++] = ++length;
            } else if (length != 0) {
                length = lps[length - 1];
            } else {
                lps[i++] = 0;
            }
        }
        return lps;
    }

    static List<Integer> kmpSearch(String txt, String pat) {
        int n = txt.length(), m = pat.length();
        int[] lps = computeLPS(pat);
        List<Integer> result = new ArrayList<>();
        int i = 0, j = 0;

        while (i < n) {
            if (txt.charAt(i) == pat.charAt(j)) { i++; j++; }

            if (j == m) {
                result.add(i - j);
                j = lps[j - 1];
            } else if (i < n && txt.charAt(i) != pat.charAt(j)) {
                if (j != 0) j = lps[j - 1];
                else        i++;
            }
        }
        return result;
    }

    public static void main(String[] args) {
        System.out.println(kmpSearch("aabaacaadaabaaba", "aaba")); // [0, 9, 12]
        System.out.println(kmpSearch("abcab", "ab"));              // [0, 3]
    }
}

