    const lps    = computeLPS(pat);
    const result = [];
    let i = 0, j = 0;

    while (i < n) {
        if (txt[i] === pat[j]) { i++; j++; }

        if (j === m) {
            result.push(i - j);
            j = lps[j - 1];
        } else if (i < n && txt[i] !== pat[j]) {
            j = j !== 0 ? lps[j - 1] : (i++, 0);
        }
    }
    return result;
}

