class Node:
    def __init__(self, val):
        self.val   = val
        self.left  = self.right = None

# Recursion: natural match for tree structure
def inorder_recursive(root):
    if not root: return []
    return inorder_recursive(root.left) + [root.val] + inorder_recursive(root.right)

# Iteration: requires manual stack (more code, less clear)
def inorder_iterative(root):
    result, stack = [], []
    curr = root
    while curr or stack:
        while curr:
            stack.append(curr)
            curr = curr.left
        curr = stack.pop()
        result.append(curr.val)
        curr = curr.right
    return result

# Both produce same result, but recursive version is clearly simpler

# DFS on a tree: recursion is the natural expression
def dfs(node):
    if not node: return
    print(node.val)
    dfs(node.left)
    dfs(node.right)

# Iterative equivalent needs explicit stack management:
def dfs_iterative(root):
    if not root: return
    stack = [root]
    while stack:
        node = stack.pop()
        print(node.val)
        if node.right: stack.append(node.right)
        if node.left:  stack.append(node.left)

def merge_sort(arr):
    if len(arr) <= 1:
        return arr
    mid   = len(arr) // 2
    left  = merge_sort(arr[:mid])    # Recursively sort left half
    right = merge_sort(arr[mid:])    # Recursively sort right half
    return merge(left, right)

# DO NOT use recursion for large n:
def sum_recursive(n):
    if n == 0: return 0
    return n + sum_recursive(n - 1)

